SINA_SMART["histo1-epithelium"] = {"lecture":"histo1-epithelium","title":"Epithelial tissue","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"histo1-epithelium:e0","text":"Epithelium: from all three germ layers; polarity, junctions, basement membrane, avascular.","topic":"Tissues and the epithelium","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-epithelium:e1","text":"Microvilli: actin core, absorption; stereocilia: immotile (epididymis, ear); cilia: motile.","topic":"Polarity: apical, lateral and basal domains","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-epithelium:e2","text":"Tight = seal; desmosome = anchor (skin); gap = communication (heart); hemidesmosome = to basement membrane.","topic":"Polarity: apical, lateral and basal domains","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-epithelium:e3","text":"Basal lamina: type IV collagen, laminin; reticular lamina: type III collagen.","topic":"Polarity: apical, lateral and basal domains","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-epithelium:e4","text":"Name = layers (simple, stratified, pseudostratified) + surface shape.","topic":"Classification","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-epithelium:e5","text":"Simple squamous: endothelium, alveoli; simple cuboidal: kidney tubules.","topic":"Classification","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-epithelium:e6","text":"Pseudostratified ciliated: airways; stratified squamous: skin, mouth, vagina.","topic":"Classification","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-epithelium:e7","text":"Transitional epithelium: urinary passages; domes when empty.","topic":"Classification","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-epithelium:e10","text":"Serous (parotid), mucous (sublingual), mixed (submandibular); merocrine, apocrine, holocrine (sebaceous).","topic":"Glands","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-epithelium:e8","text":"Goblet cell = unicellular exocrine gland.","topic":"Glands","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-epithelium:e9","text":"Simple vs compound duct; tubular, acinar, tubuloalveolar units.","topic":"Glands","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"elvkca":"a","18q8j4r":"a","sjckig":"a","1c6of4":"a","1v3cs1l":"a","h3okui":"a","uvnjw6":"a","txs8y3":"a","1ycx9tr":"a","mebrmo":"a","elku04":"a","zx3xl":"a","ztuq2j":"a","vb30qk":"a","1f6uxqf":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"histo1-epithelium:e0":{"s":0,"u":["Epithelium: from all three germ layers; polarity, junctions, basement membrane, avascular.","Epithelium comes from all three germ layers (ectoderm: epidermis; endoderm: gut, respiratory and urinary linings, liver; mesoderm: endothelium, mesothelium).","Features: cells packed close with little intercellular material , polarity , junctions , a basement membrane , no blood vessels (fed by diffusion) and mitotic activity : most epithelial cells live shorter than the body and are replaced from adult stem cells."],"dp":[]},"histo1-epithelium:e1":{"s":1,"u":["Microvilli: actin core, absorption; stereocilia: immotile (epididymis, ear); cilia: motile.","Apical domain (facing the lumen): microvilli , finger-like projections with an actin core that increase absorptive surface (small intestine); stereocilia , long immotile microvilli, absorptive in the epididymis and mechanoreceptors in inner-ear hair cells; cilia , motile, moving fluid and particles (bronchi, uterine tubes), and the sperm flagellum."],"dp":[]},"histo1-epithelium:e2":{"s":1,"u":["Tight = seal; desmosome = anchor (skin); gap = communication (heart); hemidesmosome = to basement membrane.","Tight junctions (occluding) seal, e.g. keeping gut bacteria and toxins out of the blood; desmosomes (anchoring, linked to keratin filaments) let skin stretch while holding cells together; gap junctions (communicating, connexons) spread action potentials in cardiac muscle.","It anchors the cells (via hemidesmosomes and integrins), is a mechanical barrier and lets nutrients and wastes diffuse."],"dp":[]},"histo1-epithelium:e3":{"s":1,"u":["Basal lamina: type IV collagen, laminin; reticular lamina: type III collagen.","Basal lamina (lamina lucida and lamina densa): type IV collagen , heparan sulphate, laminin, fibronectin; reticular lamina : type III (reticular) collagen and proteoglycans."],"dp":[]},"histo1-epithelium:e4":{"s":2,"u":["Name = layers (simple, stratified, pseudostratified) + surface shape.","Named by (1) number of layers , simple (one), stratified (several) or pseudostratified (one layer, nuclei at different levels), and (2) shape of the surface cells , squamous, cuboidal or columnar."],"dp":[]},"histo1-epithelium:e5":{"s":2,"u":["Simple squamous: endothelium, alveoli; simple cuboidal: kidney tubules.","Simple cuboidal: kidney tubules, gland ducts (absorption, secretion).","Simple squamous: vessel lining, lung alveoli (diffusion)."],"dp":[]},"histo1-epithelium:e6":{"s":2,"u":["Pseudostratified ciliated: airways; stratified squamous: skin, mouth, vagina.","Stratified squamous : mouth and vagina (non-keratinised), epidermis (keratinised: dead surface cells full of waterproof keratin); protection.","Named by (1) number of layers , simple (one), stratified (several) or pseudostratified (one layer, nuclei at different levels), and (2) shape of the surface cells , squamous, cuboidal or columnar."],"dp":[{"h":"Metaplasia: when epithelium changes to survive","t":"Epithelia can swap one mature type for another better able to cope with stress. In a smoker's bronchus, the ciliated pseudostratified lining is replaced by tougher stratified squamous epithelium; in chronic acid reflux the oesophagus's squamous lining becomes intestinal-type columnar epithelium with goblet cells (Barrett's oesophagus). The new tissue resists the insult but loses the old function (no cilia, so mucus is not cleared), and metaplasia can progress to dysplasia and cancer. Knowing the normal epithelium of each organ is what lets a pathologist spot the change. Source: the lecture's classification by location; standard pathology link."}]},"histo1-epithelium:e7":{"s":2,"u":["Transitional epithelium: urinary passages; domes when empty.","Transitional (urothelium) : ureters, bladder, part of the urethra; dome-shaped surface cells when empty, flattened when full; a barrier with tight junctions.","Pseudostratified columnar: respiratory passages, many gland ducts (mucus movement)."],"dp":[]},"histo1-epithelium:e10":{"s":3,"u":["Serous (parotid), mucous (sublingual), mixed (submandibular); merocrine, apocrine, holocrine (sebaceous).","Secretions: serous (thin, watery, protein-rich: parotid), mucous (thick, glycoprotein-rich: sublingual) and seromucous (mixed: submandibular).","Mechanisms: merocrine (exocytosis, most glands), apocrine (apical cytoplasm lost: lipid of milk) and holocrine (whole cell released: sebaceous gland )."],"dp":[]},"histo1-epithelium:e8":{"s":3,"u":["Goblet cell = unicellular exocrine gland.","Unicellular : the goblet cell , a mucus-secreting cell among columnar cells.","Exocrine glands keep a duct."],"dp":[]},"histo1-epithelium:e9":{"s":3,"u":["Simple vs compound duct; tubular, acinar, tubuloalveolar units.","Multicellular : by the duct, simple (unbranched) or compound (branched); by the secretory unit, tubular , acinar/alveolar (flask) or tubuloalveolar .","Types include simple tubular, simple coiled tubular (sweat glands), simple branched acinar, compound tubuloacinar."],"dp":[]}},"meta":{"elvkca":{"a":"recall","vg":"histo1-epithelium:e0/recall/1"},"18q8j4r":{"a":"recall","vg":"histo1-epithelium:e1/recall/1"},"sjckig":{"a":"recall","vg":"histo1-epithelium:e1/recall/2"},"1c6of4":{"a":"recall","vg":"histo1-epithelium:e1/recall/3"},"1v3cs1l":{"a":"recall","vg":"histo1-epithelium:e2/recall/1"},"h3okui":{"a":"recall","vg":"histo1-epithelium:e2/recall/1"},"uvnjw6":{"a":"recall","vg":"histo1-epithelium:e3/recall/1"},"txs8y3":{"a":"recall","vg":"histo1-epithelium:e0/recall/2"},"1ycx9tr":{"a":"recall","vg":"histo1-epithelium:e5/recall/1"},"mebrmo":{"a":"recall","vg":"histo1-epithelium:e7/recall/1"},"elku04":{"a":"recall","vg":"histo1-epithelium:e7/recall/1"},"zx3xl":{"a":"recall","vg":"histo1-epithelium:e6/recall/1"},"ztuq2j":{"a":"recall","vg":"histo1-epithelium:e8/recall/1"},"vb30qk":{"a":"recall","vg":"histo1-epithelium:e9/recall/1"},"1f6uxqf":{"a":"recall","vg":"histo1-epithelium:e10/recall/1"}},"explRev":"002f9b8d5a58"};
